// SettingsCatalog (M1 subset). Settings are addressed by catalog id (SettingId); the
// platform adapter maps an id to its transport (a5000: SDCom 0x1002/0x1003 paramId).
// Values are the HAL "A side" values (enum = index into the HAL value list, int = number).
// Generated by uicore/tools/gen_catalog.py from app/docs/settings_sdcom_map.tsv.
#pragma once
#include "uicore/catalog_gen.h"

namespace uicore {

enum SettingKind {
    SK_ENUM,      // value from vals[] (label, value)
    SK_LIST,      // like ENUM but the value is a number picked from a sorted list (ISO, self-timer)
    SK_INT,       // integer in [minv, maxv]
    SK_BOOL,
    SK_RO_INT,    // read-only integer
    SK_RO_ARR2    // read-only pair (shutter speed num/den)
};

struct EnumVal { const char *label; int value; };

struct SettingDef {
    int id;                // SettingId
    const char *key;       // settings_sdcom_map.tsv setting_id
    int paramId;           // SDCom param id (256+i)
    int kind;              // SettingKind
    int minv, maxv;        // SK_INT range
    const EnumVal *vals;   // SK_ENUM / SK_LIST
    int nVals;
};

extern const SettingDef kCatalog[SET_COUNT];

const SettingDef *catalogDef(int id);                 // 0 if out of range
const SettingDef *catalogByParam(int paramId);        // 0 if not in the subset
const char *catalogLabel(int id, int value);          // enum/list label or 0
bool catalogHasValue(int id, int value);
// Next valid value from `cur` in direction dir (+1/-1) for ENUM/LIST/INT; false at the end.
bool catalogNeighbor(int id, int cur, int dir, int *out);

} // namespace uicore
